  .step('critiqueB', reviewerB.call(critique), s => ({ title: s.input.title, section: s.input.section, body: s.input.body }))
  .step('merge', mergeCritiques, s => ({ a: s.steps.critiqueA, b: s.steps.critiqueB }))
