      path: '/helpdesk/events',
      port: H.slot.port(0),
      secret: H.env('HELPDESK_WEBHOOK_SECRET'),
      body: conversation,
      key: body => body.id,
      data: body => body,
      mode: 'upsert',
    }),
    rest.poll({
      name: 'helpdesk-catch-up',
      baseUrl: helpdeskUrl,
      token: helpdeskToken,
      path: '/conversations',
      interval: '10m',
      item: conversation,
      key: item => item.id,
      data: item => item,
      mode: 'upsert',
