  .do(
    escalations.create(event => ({
      key: `escalation-${event.unit.key}`,
      data: { conversation: event.unit.key, reason: `SLA breached at ${event.deadline.toISOString()}` },
    })),
    conversations.move(event => event.unit.key, escalated),
